        return f(x) @ np.linalg.lstsq(f(u), v, rcond=None)[0]
    return calibrate(lambda a: _one(_cycle(a)), v1), calibrate(lambda a: _one(np.c_[a, a*a]), v2)


def _kernels(x, z, b, c, d, n):
    groups = []
    def std(a):
        return (a-a[:n].mean(0))/np.maximum(a[:n].std(0), 1e-10)
